import React, { useState } from 'react';
import { FiPlus, FiTrash2, FiTag } from 'react-icons/fi';
import toast from 'react-hot-toast';

const COMMON_COLORS = [
  { name: 'Black',  hex: '#000000' },
  { name: 'White',  hex: '#FFFFFF' },
  { name: 'Red',    hex: '#E53935' },
  { name: 'Blue',   hex: '#1E88E5' },
  { name: 'Green',  hex: '#43A047' },
  { name: 'Yellow', hex: '#FDD835' },
  { name: 'Pink',   hex: '#E91E8C' },
  { name: 'Gray',   hex: '#757575' },
  { name: 'Brown',  hex: '#6D4C41' },
  { name: 'Navy',   hex: '#1A237E' },
];

const SIZE_PRESETS = {
  clothing: ['XS', 'S', 'M', 'L', 'XL', 'XXL'],
  shoes:    ['38', '39', '40', '41', '42', '43', '44', '45'],
};

const VariantManager = ({ variants = [], onChange }) => {
  const [newVariant, setNewVariant] = useState({
    size: '', color: '', color_hex: '', stock: '', price_adjustment: '0'
  });
  const [sizeType, setSizeType] = useState('clothing');

  const handleAdd = () => {
    if (!newVariant.size && !newVariant.color) {
      toast.error('Add at least a size or color');
      return;
    }
    if (!newVariant.stock || newVariant.stock < 0) {
      toast.error('Enter valid stock quantity');
      return;
    }

    // check for duplicates
    const exists = variants.some(
      (v) => v.size === newVariant.size && v.color === newVariant.color
    );
    if (exists) {
      toast.error('This size/color combination already exists');
      return;
    }

    onChange([...variants, { ...newVariant, stock: parseInt(newVariant.stock) }]);
    setNewVariant({ size: '', color: '', color_hex: '', stock: '', price_adjustment: '0' });
  };

  const handleRemove = (idx) => {
    onChange(variants.filter((_, i) => i !== idx));
  };

  const handleQuickAdd = (size) => {
    setNewVariant({ ...newVariant, size });
  };

  const handleColorSelect = (color) => {
    setNewVariant({ ...newVariant, color: color.name, color_hex: color.hex });
  };

  return (
    <div className="space-y-4">

      {/* Size type toggle */}
      <div className="flex gap-2">
        <button type="button" onClick={() => setSizeType('clothing')}
          className={`px-3 py-1.5 rounded-lg text-xs font-medium transition
            ${sizeType === 'clothing'
              ? 'bg-primary text-white'
              : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400'}`}>
          Clothing Sizes
        </button>
        <button type="button" onClick={() => setSizeType('shoes')}
          className={`px-3 py-1.5 rounded-lg text-xs font-medium transition
            ${sizeType === 'shoes'
              ? 'bg-primary text-white'
              : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400'}`}>
          Shoe Sizes
        </button>
      </div>

      {/* Add variant form */}
      <div className="bg-gray-50 dark:bg-gray-800 rounded-xl p-4 space-y-3">

        {/* Size quick select */}
        <div>
          <label className="block text-xs font-semibold text-gray-500 mb-1.5">
            Size
          </label>
          <div className="flex flex-wrap gap-1.5 mb-2">
            {SIZE_PRESETS[sizeType].map((s) => (
              <button key={s} type="button" onClick={() => handleQuickAdd(s)}
                className={`px-2.5 py-1 rounded-lg text-xs font-medium border
                            transition
                  ${newVariant.size === s
                    ? 'bg-primary text-white border-primary'
                    : 'bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400'
                  }`}>
                {s}
              </button>
            ))}
          </div>
          <input type="text" value={newVariant.size}
            onChange={(e) => setNewVariant({ ...newVariant, size: e.target.value })}
            placeholder="Or type custom size"
            className="w-full px-3 py-2 rounded-lg border border-gray-200
                       dark:border-gray-700 bg-white dark:bg-gray-900
                       dark:text-white text-sm focus:outline-none
                       focus:ring-2 focus:ring-primary" />
        </div>

        {/* Color quick select */}
        <div>
          <label className="block text-xs font-semibold text-gray-500 mb-1.5">
            Color
          </label>
          <div className="flex flex-wrap gap-1.5 mb-2">
            {COMMON_COLORS.map((c) => (
              <button key={c.name} type="button" onClick={() => handleColorSelect(c)}
                title={c.name}
                className={`w-7 h-7 rounded-full border-2 transition
                  ${newVariant.color === c.name
                    ? 'border-primary scale-110'
                    : 'border-gray-200 dark:border-gray-700'}`}
                style={{ backgroundColor: c.hex }} />
            ))}
          </div>
          <input type="text" value={newVariant.color}
            onChange={(e) => setNewVariant({ ...newVariant, color: e.target.value })}
            placeholder="Or type custom color"
            className="w-full px-3 py-2 rounded-lg border border-gray-200
                       dark:border-gray-700 bg-white dark:bg-gray-900
                       dark:text-white text-sm focus:outline-none
                       focus:ring-2 focus:ring-primary" />
        </div>

        {/* Stock and price adjustment */}
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1.5">
              Stock
            </label>
            <input type="number" value={newVariant.stock} min={0}
              onChange={(e) => setNewVariant({ ...newVariant, stock: e.target.value })}
              placeholder="0"
              className="w-full px-3 py-2 rounded-lg border border-gray-200
                         dark:border-gray-700 bg-white dark:bg-gray-900
                         dark:text-white text-sm focus:outline-none
                         focus:ring-2 focus:ring-primary" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1.5">
              Price +/- (KES)
            </label>
            <input type="number" value={newVariant.price_adjustment}
              onChange={(e) => setNewVariant({ ...newVariant, price_adjustment: e.target.value })}
              placeholder="0"
              className="w-full px-3 py-2 rounded-lg border border-gray-200
                         dark:border-gray-700 bg-white dark:bg-gray-900
                         dark:text-white text-sm focus:outline-none
                         focus:ring-2 focus:ring-primary" />
          </div>
        </div>

        <button type="button" onClick={handleAdd}
          className="w-full flex items-center justify-center gap-2 py-2.5
                     bg-primary text-white text-sm font-semibold rounded-lg
                     hover:bg-primary-dark transition">
          <FiPlus size={16} /> Add Variant
        </button>
      </div>

      {/* Existing variants list */}
      {variants.length > 0 && (
        <div className="space-y-2">
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
            {variants.length} Variant{variants.length !== 1 ? 's' : ''} Added
          </p>
          {variants.map((v, idx) => (
            <div key={idx}
              className="flex items-center justify-between bg-white
                         dark:bg-gray-900 border border-gray-200
                         dark:border-gray-700 rounded-xl p-3">
              <div className="flex items-center gap-3">
                {v.color_hex && (
                  <div className="w-6 h-6 rounded-full border border-gray-200
                                  flex-shrink-0"
                    style={{ backgroundColor: v.color_hex }} />
                )}
                <div>
                  <p className="text-sm font-medium dark:text-white">
                    {[v.size, v.color].filter(Boolean).join(' / ') || 'Default'}
                  </p>
                  <p className="text-xs text-gray-500">
                    Stock: {v.stock}
                    {v.price_adjustment !== 0 && (
                      <span className="ml-2">
                        {v.price_adjustment > 0 ? '+' : ''}KES {v.price_adjustment}
                      </span>
                    )}
                  </p>
                </div>
              </div>
              <button type="button" onClick={() => handleRemove(idx)}
                className="p-1.5 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20
                           transition">
                <FiTrash2 size={14} className="text-danger" />
              </button>
            </div>
          ))}
        </div>
      )}

      {variants.length === 0 && (
        <div className="text-center py-6 bg-gray-50 dark:bg-gray-800 rounded-xl">
          <FiTag size={24} className="text-gray-300 mx-auto mb-2" />
          <p className="text-xs text-gray-400">
            No variants added. Add sizes/colors above, or leave empty for a
            single-variant product.
          </p>
        </div>
      )}
    </div>
  );
};

export default VariantManager;
