import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  FiHeart, FiShoppingCart, FiStar, FiMinus, FiPlus,
  FiTruck, FiShield, FiRefreshCw, FiChevronRight,
  FiCheck, FiMessageSquare, FiThumbsUp, FiUser
} from 'react-icons/fi';
import toast from 'react-hot-toast';
import { productsAPI, cartAPI, reviewsAPI } from '../../api/endpoints';
import useAuthStore from '../../store/authStore';
import useCartStore from '../../store/cartStore';

// ── Star rating display ──────────────────────────────────────
const StarRating = ({ rating, size = 14 }) => (
  <div className="flex items-center gap-0.5">
    {[1, 2, 3, 4, 5].map((s) => (
      <FiStar key={s} size={size}
        className={s <= Math.round(rating) ? 'text-accent fill-accent' : 'text-gray-300'}
        fill={s <= Math.round(rating) ? 'currentColor' : 'none'} />
    ))}
  </div>
);

// ── Review item ───────────────────────────────────────────────
const ReviewItem = ({ review, onMarkHelpful }) => {
  const [helped, setHelped] = useState(false);

  const handleHelpful = async () => {
    if (helped) return;
    setHelped(true);
    onMarkHelpful(review.id);
  };

  return (
    <div className="border-b border-gray-100 dark:border-gray-800 py-4 last:border-0">
      <div className="flex items-start gap-3">
        <div className="w-9 h-9 bg-primary rounded-full flex items-center
                        justify-center flex-shrink-0">
          <span className="text-white text-xs font-bold">
            {review.username?.[0]?.toUpperCase() || <FiUser size={14} />}
          </span>
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <p className="text-sm font-semibold dark:text-white">{review.username}</p>
            {review.is_verified && (
              <span className="text-xs bg-green-100 text-green-700 px-1.5 py-0.5
                               rounded flex items-center gap-0.5">
                <FiCheck size={10} /> Verified
              </span>
            )}
          </div>
          <StarRating rating={review.rating} size={12} />
          {review.title && (
            <p className="text-sm font-medium dark:text-white mt-2">{review.title}</p>
          )}
          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1 leading-relaxed">
            {review.comment}
          </p>
          <div className="flex items-center gap-4 mt-2">
            <p className="text-xs text-gray-400">
              {new Date(review.created_at).toLocaleDateString('en-KE', {
                day: 'numeric', month: 'short', year: 'numeric'
              })}
            </p>
            <button onClick={handleHelpful}
              className={`flex items-center gap-1 text-xs transition
                ${helped ? 'text-primary' : 'text-gray-400 hover:text-primary'}`}>
              <FiThumbsUp size={12} /> Helpful ({review.helpful + (helped ? 1 : 0)})
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// ── Write review form ────────────────────────────────────────
const ReviewForm = ({ productSlug, onSubmitted }) => {
  const [rating,  setRating]  = useState(0);
  const [hover,   setHover]   = useState(0);
  const [title,   setTitle]   = useState('');
  const [comment, setComment] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!rating) { toast.error('Please select a rating'); return; }
    if (!comment.trim()) { toast.error('Please write a comment'); return; }

    setSubmitting(true);
    try {
      await reviewsAPI.addReview({
        product: undefined, // backend infers from slug in URL — adjust if needed
        rating, title, comment,
      }, productSlug);
      toast.success('Review submitted!');
      setRating(0); setTitle(''); setComment('');
      onSubmitted();
    } catch (err) {
      toast.error(err.response?.data?.[0] || err.response?.data?.detail ||
                   'Failed to submit review');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}
      className="bg-gray-50 dark:bg-gray-800 rounded-xl p-4 space-y-3">
      <p className="text-sm font-semibold dark:text-white">Write a Review</p>

      <div className="flex items-center gap-1">
        {[1, 2, 3, 4, 5].map((s) => (
          <button key={s} type="button"
            onClick={() => setRating(s)}
            onMouseEnter={() => setHover(s)}
            onMouseLeave={() => setHover(0)}
            className="transition">
            <FiStar size={22}
              className={s <= (hover || rating) ? 'text-accent fill-accent' : 'text-gray-300'}
              fill={s <= (hover || rating) ? 'currentColor' : 'none'} />
          </button>
        ))}
      </div>

      <input type="text" value={title} onChange={(e) => setTitle(e.target.value)}
        placeholder="Review title (optional)"
        className="w-full px-3 py-2 rounded-lg border border-gray-200
                   dark:border-gray-700 bg-white dark:bg-gray-900 dark:text-white
                   text-sm focus:outline-none focus:ring-2 focus:ring-primary" />

      <textarea value={comment} onChange={(e) => setComment(e.target.value)}
        rows={3} placeholder="Share your experience with this product..."
        className="w-full px-3 py-2 rounded-lg border border-gray-200
                   dark:border-gray-700 bg-white dark:bg-gray-900 dark:text-white
                   text-sm focus:outline-none focus:ring-2 focus:ring-primary
                   resize-none" />

      <button type="submit" disabled={submitting}
        className="px-5 py-2 bg-primary text-white text-sm font-semibold
                   rounded-lg hover:bg-primary-dark transition disabled:opacity-60">
        {submitting ? 'Submitting...' : 'Submit Review'}
      </button>
    </form>
  );
};

// ── Main Page ─────────────────────────────────────────────────
const ProductDetailPage = () => {
  const { slug }    = useParams();
  const navigate    = useNavigate();
  const { isAuth }  = useAuthStore();
  const { setCart } = useCartStore();

  const [product,    setProduct]    = useState(null);
  const [loading,    setLoading]    = useState(true);
  const [activeImg,  setActiveImg]  = useState(0);
  const [quantity,   setQuantity]   = useState(1);
  const [adding,     setAdding]     = useState(false);
  const [wishlisted, setWishlisted] = useState(false);

  const [selectedSize,  setSelectedSize]  = useState('');
  const [selectedColor, setSelectedColor] = useState('');

  const [reviews,    setReviews]    = useState([]);
  const [ratingSummary, setRatingSummary] = useState(null);
  const [showReviewForm, setShowReviewForm] = useState(false);

  useEffect(() => {
    fetchProduct();
    fetchReviews();
    window.scrollTo(0, 0);
  // eslint-disable-next-line
  }, [slug]);

  const fetchProduct = async () => {
    setLoading(true);
    try {
      const res = await productsAPI.getDetail(slug);
      setProduct(res.data);
      // auto-select first available variant
      if (res.data.variants?.length > 0) {
        const first = res.data.variants[0];
        setSelectedSize(first.size || '');
        setSelectedColor(first.color || '');
      }
    } catch {
      toast.error('Product not found');
      navigate('/shop');
    } finally {
      setLoading(false);
    }
  };

  const fetchReviews = async () => {
    try {
      const [reviewsRes, summaryRes] = await Promise.all([
        reviewsAPI.getReviews(slug),
        reviewsAPI.getRating ? reviewsAPI.getRating(slug) : Promise.resolve({ data: null }),
      ]);
      setReviews(reviewsRes.data.results || reviewsRes.data || []);
      if (summaryRes.data) setRatingSummary(summaryRes.data);
    } catch {
      // reviews optional
    }
  };

  const handleMarkHelpful = async (reviewId) => {
    try {
      await reviewsAPI.markHelpful?.(reviewId);
    } catch {}
  };

  // find matching variant based on selected size/color
  const selectedVariant = product?.variants?.find(
    (v) => v.size === selectedSize && v.color === selectedColor
  );

  const currentStock = product?.has_variants
    ? (selectedVariant?.stock ?? 0)
    : product?.stock;

  const currentPrice = product?.has_variants && selectedVariant
    ? selectedVariant.final_price
    : product?.discounted_price;

  const handleAddToCart = async () => {
    if (!isAuth) { toast.error('Please login to add to cart'); return; }
    if (product.has_variants && !selectedVariant) {
      toast.error('Please select size/color'); return;
    }
    if (currentStock < quantity) { toast.error('Not enough stock'); return; }

    setAdding(true);
    try {
      const payload = { product_id: product.id, quantity };
      if (selectedVariant) payload.variant_id = selectedVariant.id;
      const res = await cartAPI.addItem(payload);
      setCart(res.data);
      toast.success('Added to cart');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to add to cart');
    } finally {
      setAdding(false);
    }
  };

  const handleWishlist = async () => {
    if (!isAuth) { toast.error('Please login'); return; }
    try {
      if (!wishlisted) {
        await productsAPI.addWishlist({ product_id: product.id });
        setWishlisted(true);
        toast.success('Added to wishlist');
      } else {
        toast.success('Already in wishlist');
      }
    } catch {
      toast.error('Failed to update wishlist');
    }
  };

  if (loading) return (
    <div className="max-w-6xl mx-auto px-4 py-8 animate-pulse">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="aspect-square bg-gray-100 dark:bg-gray-800 rounded-2xl" />
        <div className="space-y-4">
          <div className="h-6 bg-gray-100 dark:bg-gray-800 rounded w-3/4" />
          <div className="h-4 bg-gray-100 dark:bg-gray-800 rounded w-1/2" />
          <div className="h-10 bg-gray-100 dark:bg-gray-800 rounded w-1/3" />
        </div>
      </div>
    </div>
  );

  if (!product) return null;

  const images = product.images?.length > 0
    ? product.images
    : [{ image: null }];

  const uniqueSizes  = [...new Set(product.variants?.map((v) => v.size).filter(Boolean))];
  const uniqueColors = [...new Map(
    (product.variants || [])
      .filter((v) => v.color)
      .map((v) => [v.color, { name: v.color, hex: v.color_hex }])
  ).values()];

  return (
    <div className="bg-sky-gray dark:bg-gray-950 min-h-screen">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-6">

        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-xs text-gray-500
                        dark:text-gray-400 mb-6">
          <Link to="/" className="hover:text-primary">Home</Link>
          <FiChevronRight size={12} />
          <Link to="/shop" className="hover:text-primary">Shop</Link>
          <FiChevronRight size={12} />
          <Link to={`/shop?category=${product.category?.slug}`}
            className="hover:text-primary">
            {product.category?.name}
          </Link>
          <FiChevronRight size={12} />
          <span className="text-gray-700 dark:text-gray-300 truncate max-w-[150px]">
            {product.name}
          </span>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">

          {/* Image gallery */}
          <div>
            <div className="bg-white dark:bg-gray-900 rounded-2xl border
                            border-gray-200 dark:border-gray-800 p-4 mb-3
                            aspect-square flex items-center justify-center
                            overflow-hidden">
              {images[activeImg]?.image ? (
                <img src={images[activeImg].image} alt={product.name}
                     className="max-w-full max-h-full object-contain" />
              ) : (
                <FiShoppingCart size={64} className="text-gray-200" />
              )}
            </div>

            {images.length > 1 && (
              <div className="flex gap-2 overflow-x-auto pb-1">
                {images.map((img, idx) => (
                  <button key={idx} onClick={() => setActiveImg(idx)}
                    className={`flex-shrink-0 w-16 h-16 rounded-xl overflow-hidden
                               border-2 transition
                      ${activeImg === idx
                        ? 'border-primary'
                        : 'border-gray-200 dark:border-gray-700'}`}>
                    {img.image ? (
                      <img src={img.image} alt=""
                           className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-gray-100 dark:bg-gray-800" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Info */}
          <div>
            <p className="text-xs text-primary font-semibold uppercase
                          tracking-wide mb-1">
              {product.category?.name}
            </p>
            <h1 className="font-heading text-2xl font-bold dark:text-white mb-2">
              {product.name}
            </h1>

            <div className="flex items-center gap-3 mb-4">
              {ratingSummary && ratingSummary.total_reviews > 0 ? (
                <>
                  <StarRating rating={ratingSummary.average_rating} size={16} />
                  <span className="text-sm text-gray-500 dark:text-gray-400">
                    {ratingSummary.average_rating.toFixed(1)} ({ratingSummary.total_reviews} reviews)
                  </span>
                </>
              ) : (
                <span className="text-sm text-gray-400">No reviews yet</span>
              )}
              <span className="text-xs text-gray-400">·</span>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {product.views_count} views
              </span>
            </div>

            {/* Price */}
            <div className="flex items-baseline gap-3 mb-1">
              <span className="font-heading text-3xl font-bold text-primary">
                KES {Number(currentPrice || 0).toLocaleString()}
              </span>
              {product.discount > 0 && !product.has_variants && (
                <span className="text-lg text-gray-400 line-through">
                  KES {Number(product.price).toLocaleString()}
                </span>
              )}
            </div>
            {product.discount > 0 && (
              <span className="inline-block bg-danger/10 text-danger text-xs
                               font-bold px-2 py-0.5 rounded-lg mb-4">
                -{product.discount}% OFF
              </span>
            )}

            {/* Stock status */}
            <div className="mb-5">
              {currentStock > 0 ? (
                <span className="flex items-center gap-1.5 text-sm text-green-600
                                 font-medium">
                  <FiCheck size={14} /> In Stock
                  {currentStock <= 5 && ` (only ${currentStock} left)`}
                </span>
              ) : (
                <span className="text-sm text-danger font-medium">Out of Stock</span>
              )}
            </div>

            {/* Size selector */}
            {product.has_variants && uniqueSizes.length > 0 && (
              <div className="mb-4">
                <p className="text-sm font-semibold dark:text-white mb-2">
                  Size
                </p>
                <div className="flex flex-wrap gap-2">
                  {uniqueSizes.map((size) => (
                    <button key={size} onClick={() => setSelectedSize(size)}
                      className={`px-4 py-2 rounded-xl border-2 text-sm font-medium
                                  transition
                        ${selectedSize === size
                          ? 'border-primary bg-primary text-white'
                          : 'border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:border-primary'
                        }`}>
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Color selector */}
            {product.has_variants && uniqueColors.length > 0 && (
              <div className="mb-5">
                <p className="text-sm font-semibold dark:text-white mb-2">
                  Color {selectedColor && `· ${selectedColor}`}
                </p>
                <div className="flex flex-wrap gap-2">
                  {uniqueColors.map((c) => (
                    <button key={c.name} onClick={() => setSelectedColor(c.name)}
                      title={c.name}
                      className={`w-9 h-9 rounded-full border-2 transition
                        ${selectedColor === c.name
                          ? 'border-primary scale-110'
                          : 'border-gray-200 dark:border-gray-700'}`}
                      style={{ backgroundColor: c.hex || '#ccc' }} />
                  ))}
                </div>
              </div>
            )}

            {/* Quantity + Add to cart */}
            <div className="flex items-center gap-3 mb-5">
              <div className="flex items-center border-2 border-gray-200
                              dark:border-gray-700 rounded-xl">
                <button onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  className="p-3 hover:bg-gray-50 dark:hover:bg-gray-800 transition">
                  <FiMinus size={14} className="dark:text-white" />
                </button>
                <span className="px-4 font-semibold dark:text-white">{quantity}</span>
                <button onClick={() => setQuantity(quantity + 1)}
                  className="p-3 hover:bg-gray-50 dark:hover:bg-gray-800 transition">
                  <FiPlus size={14} className="dark:text-white" />
                </button>
              </div>

              <button onClick={handleAddToCart}
                disabled={adding || currentStock === 0}
                className="flex-1 flex items-center justify-center gap-2 py-3
                           bg-primary text-white font-bold rounded-xl
                           hover:bg-primary-dark transition disabled:opacity-50
                           disabled:cursor-not-allowed">
                <FiShoppingCart size={18} />
                {adding ? 'Adding...' : currentStock === 0 ? 'Out of Stock' : 'Add to Cart'}
              </button>

              <button onClick={handleWishlist}
                className="p-3 border-2 border-gray-200 dark:border-gray-700
                           rounded-xl hover:border-primary transition">
                <FiHeart size={18}
                  className={wishlisted ? 'text-primary fill-primary' : 'text-gray-400'}
                  fill={wishlisted ? 'currentColor' : 'none'} />
              </button>
            </div>

            {/* Trust badges */}
            <div className="grid grid-cols-3 gap-3 pt-5 border-t border-gray-200
                            dark:border-gray-800">
              {[
                { icon: FiTruck,     label: 'Fast Delivery' },
                { icon: FiShield,    label: 'M-Pesa Secure' },
                { icon: FiRefreshCw, label: '7-Day Returns' },
              ].map((b) => (
                <div key={b.label} className="text-center">
                  <b.icon size={20} className="text-primary mx-auto mb-1" />
                  <p className="text-xs text-gray-500 dark:text-gray-400">{b.label}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Description */}
        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200
                        dark:border-gray-800 p-6 mb-6">
          <h2 className="font-heading font-bold text-lg dark:text-white mb-3">
            Product Description
          </h2>
          <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed
                        whitespace-pre-line">
            {product.description}
          </p>
        </div>

        {/* Reviews */}
        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200
                        dark:border-gray-800 p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-heading font-bold text-lg dark:text-white
                           flex items-center gap-2">
              <FiMessageSquare className="text-primary" />
              Customer Reviews
            </h2>
            {isAuth && (
              <button onClick={() => setShowReviewForm(!showReviewForm)}
                className="text-sm text-primary font-medium hover:underline">
                {showReviewForm ? 'Cancel' : 'Write a Review'}
              </button>
            )}
          </div>

          {/* Rating summary */}
          {ratingSummary && ratingSummary.total_reviews > 0 && (
            <div className="flex items-center gap-6 mb-6 pb-6 border-b
                            border-gray-100 dark:border-gray-800">
              <div className="text-center">
                <p className="font-heading text-3xl font-bold dark:text-white">
                  {ratingSummary.average_rating.toFixed(1)}
                </p>
                <StarRating rating={ratingSummary.average_rating} size={14} />
                <p className="text-xs text-gray-400 mt-1">
                  {ratingSummary.total_reviews} reviews
                </p>
              </div>
              <div className="flex-1 space-y-1">
                {[5, 4, 3, 2, 1].map((star) => {
                  const count = ratingSummary[
                    ['', 'one_star', 'two_star', 'three_star', 'four_star', 'five_star'][star]
                  ] || 0;
                  const pct = ratingSummary.total_reviews
                    ? (count / ratingSummary.total_reviews) * 100 : 0;
                  return (
                    <div key={star} className="flex items-center gap-2">
                      <span className="text-xs text-gray-500 w-3">{star}</span>
                      <FiStar size={10} className="text-accent fill-accent" />
                      <div className="flex-1 h-1.5 bg-gray-100 dark:bg-gray-800
                                      rounded-full overflow-hidden">
                        <div className="h-full bg-accent rounded-full"
                          style={{ width: `${pct}%` }} />
                      </div>
                      <span className="text-xs text-gray-400 w-6">{count}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Review form */}
          <AnimatePresence>
            {showReviewForm && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="mb-6 overflow-hidden">
                <ReviewForm productSlug={slug}
                  onSubmitted={() => { setShowReviewForm(false); fetchReviews(); }} />
              </motion.div>
            )}
          </AnimatePresence>

          {/* Reviews list */}
          {reviews.length > 0 ? (
            <div>
              {reviews.map((review) => (
                <ReviewItem key={review.id} review={review}
                  onMarkHelpful={handleMarkHelpful} />
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <p className="text-gray-400 text-sm">
                No reviews yet. Be the first to review this product!
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductDetailPage;
